import {fishLabSnapshot} from './fish-lab-model.js';import {t,getLocale} from './locales.js';
const expanded=new Set();
/** Optional, current-state disclosure. Native elements/textContent only; no dispatch, write or second clock. @param {import('./engine.js').State} state @param {import('./fish-state.js').FishPond} p @param {HTMLElement} host */
export function renderFishLab(state,p,host){const s=fishLabSnapshot(state,p),details=document.createElement('details'),summary=document.createElement('summary'),disclosure=document.createElement('p'),values=document.createElement('dl'),why=document.createElement('p'),money=document.createElement('p');details.className='fish-lab';details.dataset.fishLab=String(p.id);details.open=expanded.has(p.id);details.addEventListener('toggle',()=>{if(details.isConnected){if(details.open)expanded.add(p.id);else expanded.delete(p.id);}});summary.textContent=t('engineeringLab')+' · '+t('fishPondLabel')+' '+p.id;disclosure.textContent=t('fishLabDisclosure');disclosure.className='market-note';values.className='inspect-values';const number=(/** @type {number|null} */x,d=2)=>x===null?'—':x.toLocaleString(getLocale(),{maximumFractionDigits:d});const rows=[['fishLabOxygen',number(s.oxygenMgL)+' mg/L','oxygen'],['fishLabTan',number(s.tanMgL)+' mg/L','tan'],['fishLabPh',number(s.ph,1),'ph'],['fishLabTemp',number(s.tempC,1)+' °C','temp'],['fishCount',number(s.count,0),'count'],['fishLabBiomass',number(s.biomassKg)+' kg','biomass'],['fishLabDensity',number(s.densityKgM3)+' kg/m³','density'],['fishLabFeed',number(s.offeredG,0)+' / '+number(s.eatenG,0)+' g','feed'],['fishLabWaste',number(s.wasteG,0)+' / '+number(s.sludgeG,0)+' g','waste'],['fishLabGrowth',number(s.growthG,0)+' g','growth'],['fishLabFcr',number(s.fcr),'fcr'],['fishLabSales',number(s.sales,0)+' '+t('coins'),'sales'],['fishLabBonus',number(s.bonus,0)+' '+t('coins'),'bonus'],['fishLabOperating',number(s.operating,0)+' '+t('coins'),'operating'],['fishLabCapital',number(s.capital,0)+' '+t('coins'),'capital'],['fishLabMargin',number(s.cashMargin,0)+' '+t('coins'),'margin'],['fishLabUnitSales',number(s.salesPerKg)+' '+t('coins')+'/kg','unit-sales'],['fishLabUnitCost',number(s.operatingPerKg)+' '+t('coins')+'/kg','unit-cost']];for(const [label,value,key]of rows){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=t(label);dd.textContent=value;dd.dataset.fishMetric=key;values.append(dt,dd);}why.dataset.fishLabWhy='';why.textContent=t('whyThisHappens')+': '+t('fishLabFactors')+' '+Object.entries(s.factors).map(([key,value])=>t('fishFactor_'+key)+' '+number(value/10,1)+'%').join(' · ')+'. '+t('fishWaterDisclaimer');money.textContent=t('fishLabCashNote');const grades=document.createElement('p');grades.textContent=t('grade')+': '+(s.grades.map(c=>c.count+' × '+c.massG+' g: '+c.grade).join(' · ')||t('fishEmpty'));details.append(summary,disclosure,values,why,money,grades);
const ns='http://www.w3.org/2000/svg';for(const key of ['oxygen','tan','growth']){const figure=document.createElement('figure'),caption=document.createElement('figcaption'),svg=document.createElementNS(ns,'svg'),line=document.createElementNS(ns,'polyline'),series=s.history.map(h=>key==='oxygen'?h.oxygenMg/p.volumeL:key==='tan'?h.tanMg/p.volumeL:h.growthG),top=Math.max(1,...series);caption.textContent=t('fishTrend_'+key)+' · '+series.length+' '+t('hourlySamples')+' · 0–'+number(top)+(key==='growth'?' g':' mg/L');svg.setAttribute('viewBox','0 0 300 90');svg.setAttribute('role','img');svg.setAttribute('aria-label',caption.textContent);svg.dataset.fishTrend=key;line.setAttribute('points',series.map((v,i)=>(10+280*i/Math.max(1,series.length-1)).toFixed(2)+','+(78-65*v/top).toFixed(2)).join(' '));line.setAttribute('fill','none');line.setAttribute('stroke','#477f75');line.setAttribute('stroke-width','2');svg.append(line);figure.append(caption,svg);details.append(figure);}host.append(details);}
